#' Co-Testing Analysis (Python)
#'
#' 
#' @param data .
#' @param name1 .
#' @param sens1 .
#' @param spec1 .
#' @param name2 .
#' @param sens2 .
#' @param spec2 .
#' @param prevalence .
#' @param indep .
#' @param depPos .
#' @param depNeg .
#' @param ci .
#' @param nSens1 .
#' @param nSpec1 .
#' @param nSens2 .
#' @param nSpec2 .
#' @param nPrev .
#' @param ciWidth .
#' @param draws .
#' @param seed .
#' @param showPlot .
#' @param showConsole .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$summary} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$params} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$posttest} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$intervals} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$probPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$joint} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$dependence} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$console} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$params$asDF}
#'
#' \code{as.data.frame(results$params)}
#'
#' @export
pycotest <- function(
    data,
    name1 = "",
    sens1 = 0.8,
    spec1 = 0.9,
    name2 = "",
    sens2 = 0.75,
    spec2 = 0.95,
    prevalence = 0.1,
    indep = FALSE,
    depPos = 0.05,
    depNeg = 0.05,
    ci = FALSE,
    nSens1 = 0,
    nSpec1 = 0,
    nSens2 = 0,
    nSpec2 = 0,
    nPrev = 0,
    ciWidth = 95,
    draws = 20000,
    seed = 1,
    showPlot = FALSE,
    showConsole = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("pycotest requires jmvcore to be installed (restart may be required)")

    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame())


    options <- pycotestOptions$new(
        name1 = name1,
        sens1 = sens1,
        spec1 = spec1,
        name2 = name2,
        sens2 = sens2,
        spec2 = spec2,
        prevalence = prevalence,
        indep = indep,
        depPos = depPos,
        depNeg = depNeg,
        ci = ci,
        nSens1 = nSens1,
        nSpec1 = nSpec1,
        nSens2 = nSens2,
        nSpec2 = nSpec2,
        nPrev = nPrev,
        ciWidth = ciWidth,
        draws = draws,
        seed = seed,
        showPlot = showPlot,
        showConsole = showConsole)

    analysis <- pycotestClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

